#include <bits/stdc++.h>
using namespace std;
#define MODUL 1000000007
#define MAX_LEVEL 33
#define LL long long
LL arrayBits[MAX_LEVEL*2], nValInput, mValInput;

struct MatrixStruct {
    LL matrixData[MAX_LEVEL][MAX_LEVEL];
    inline MatrixStruct operator*(const MatrixStruct &other) const {
        MatrixStruct result;
        memset(result.matrixData, 0, sizeof(result.matrixData));
        for (int i=0; i<=mValInput; ++i) {
            for (int j=0; j<=mValInput; ++j) {
                for (int k=0; k<=mValInput; ++k) {
                    result.matrixData[i][j]=(result.matrixData[i][j]+matrixData[i][k]*other.matrixData[k][j])%MODUL;
                }
            }
        }
        return result;
    }
};

int getNumber() {
    int x=0, sign=1;
    char ch=getchar();
    while (ch<'0' || ch>'9') {
        if (ch=='-') sign=-1;
        ch=getchar();
    }
    while (ch>='0' && ch<='9') {
        x=x*10+ch-'0'; ch=getchar();
    }
    return x*sign;
}

int main() {
    nValInput=getNumber(); mValInput=getNumber();
    int tempN=nValInput, len=-1;
    while (tempN) {
