        for (int j=0; j<=mValInput; ++j) {
            A[i][0].matrixData[j][j]=1;
        }
        if (i==0) {
            for (int j=0; j<mValInput; ++j) {
                A[i][j].matrixData[mValInput][mValInput]=1;
                for (int k=0; k<mValInput; ++k) {
                    if (k!=j) {
                        A[i][j].matrixData[k][k]=1;
                        for (int l=0; l<=mValInput; ++l) A[i][j].matrixData[k][l]=1;
                    }
                }
            }
        } else {
            for (int j=0; j<mValInput; ++j) {
