                else A[i][j]=S[i-1][j]*P[i-1][j-1];
            }
        }
        P[i][0]=A[i][0];
        for (int j=1; j<mValInput; ++j) P[i][j]=P[i][j-1]*A[i][j];
        S[i][mValInput-1]=A[i][mValInput-1];
        for (int j=mValInput-2; j>=0; --j) S[i][j]=A[i][j]*S[i][j+1];
    }
    int j=0;
    for (int i=len-1; i>=0; --i) {
